using Core;
using UI.Framework.Base;
using UI.Framework.Manager;
using UnityEngine;

namespace UI
{
    /// <summary>
    /// 任务弹窗 Screen — 任务激活时弹出，任务结束时关闭。
    ///
    /// 内部包含三个子控件：
    ///   TaskNotice      — 任务名称、倒计时、进度
    ///   TaskPreface     — 任务序言文字（浮现动画）
    ///   DirectionIndicator — 任务目标方向指示器
    ///
    /// 生命周期：
    ///   ShowNotice → Open() → 填充数据 → OnAfterOpen 子控件浮现
    ///   HideNotice → OnBeforeClose 子控件隐藏 → Close() → 弹窗收起
    /// </summary>
    public class TaskScreen : UIScreen
    {
        [Header("任务 UI 组件引用（留空自动查找子物体）")]
        [SerializeField] private TaskNotice taskNotice;
        [SerializeField] private TaskPreface taskPreface;
        [SerializeField] private DirectionIndicator directionIndicator;

        // 缓存 ShowNotice 事件数据，供 OnBeforeOpen 使用
        private TaskUIUpdateData _pendingData;

        // ──────────────────────────────────────────────
        //  UIScreen 生命周期
        // ──────────────────────────────────────────────

        protected override void Awake()
        {
            screenId = "TaskScreen";
            defaultLayer = Framework.UILayer.HUD;  // HUD 层，常驻显示
            closeOnEsc = false;           // 不允许按 Esc 关闭
            useMask = false;              // 不需要半透明遮罩

            base.Awake();   // 会 SetActive(false)，一开始不可见

            UIManager.Instance.RegisterScreen(this);

            // 自动查找子组件
            if (taskNotice == null)
                taskNotice = GetComponentInChildren<TaskNotice>(true);
            if (taskPreface == null)
                taskPreface = GetComponentInChildren<TaskPreface>(true);
            if (directionIndicator == null)
                directionIndicator = GetComponentInChildren<DirectionIndicator>(true);

            // 立即订阅（不依赖 OnEnable，因为一开始是 inactive）
            SubscribeEvents();
        }

        protected void OnDestroy()
        {
            UnsubscribeEvents();
        }

        // ──────────────────────────────────────────────
        //  Channel 订阅
        // ──────────────────────────────────────────────

        protected override void SubscribeEvents()
        {
            if (EventChannelLocator.MainContainer?.taskUIChannel != null)
                EventChannelLocator.MainContainer.taskUIChannel.RegisterListener(OnTaskUIEvent);
        }

        protected override void UnsubscribeEvents()
        {
            if (EventChannelLocator.MainContainer?.taskUIChannel != null)
                EventChannelLocator.MainContainer.taskUIChannel.UnregisterListener(OnTaskUIEvent);
        }

        // ──────────────────────────────────────────────
        //  事件处理
        // ──────────────────────────────────────────────

        private void OnTaskUIEvent(TaskUIUpdateData data)
        {
            switch (data.eventType)
            {
                case TaskUIEventType.ShowNotice:
                    HandleShowNotice(data);
                    break;

                case TaskUIEventType.HideNotice:
                    HandleHideNotice();
                    break;

                case TaskUIEventType.UpdateTime:
                    if (taskNotice != null)
                        taskNotice.UpDateTime(data.timeString);
                    break;

                case TaskUIEventType.UpdateProgress:
                    if (taskNotice != null)
                        taskNotice.Notice_Data($"{data.data}");
                    break;

                case TaskUIEventType.SetIndicator:
                    if (directionIndicator != null)
                        directionIndicator.SetTargetAndImage(data.targetPosition, data.taskId);
                    break;

                case TaskUIEventType.ClearIndicator:
                    if (directionIndicator != null)
                        directionIndicator.SetTargetName(null);
                    break;

                case TaskUIEventType.NoticeData:
                    if (taskNotice != null)
                        taskNotice.Notice_Data(data.data);
                    break;
            }
        }

        private void HandleShowNotice(TaskUIUpdateData data)
        {
            _pendingData = data;

            if (!IsOpen)
                Open();           // 第一次：打开弹窗
            else
                UpdateContent(data); // 已打开：直接更新内容
        }

        private void HandleHideNotice()
        {
            if (IsOpen)
                Close();
        }

        // ──────────────────────────────────────────────
        //  Open / Close 流程钩子
        // ──────────────────────────────────────────────

        /// <summary>打开弹窗前填充数据</summary>
        protected override void OnBeforeOpen()
        {
            base.OnBeforeOpen();
            UpdateContent(_pendingData);
        }

        /// <summary>打开弹窗后播子控件浮现动画</summary>
        protected override void OnAfterOpen()
        {
            base.OnAfterOpen();

            if (taskPreface != null)
                taskPreface.PlayTextAnimation(true);
        }

        /// <summary>关闭弹窗前先播子控件隐藏动画</summary>
        protected override void OnBeforeClose()
        {
            base.OnBeforeClose();

            if (taskNotice != null)
                taskNotice.PlaySlideAnimation(false);
            if (taskPreface != null)
                taskPreface.PlayTextAnimation(false);
            if (directionIndicator != null)
                directionIndicator.SetTargetName(null);
        }

        // ──────────────────────────────────────────────
        //  内部方法
        // ──────────────────────────────────────────────

        private void UpdateContent(TaskUIUpdateData data)
        {
            if (taskNotice != null)
                taskNotice.SetInfo(data.taskName, data.description, data.limitTime, data.requiredCount);
            if (taskPreface != null)
                taskPreface.SetText(data.description);
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using DG.Tweening;
using TMPro;
using Unity.VisualScripting;
using UnityEngine;
using Sequence = DG.Tweening.Sequence;

namespace UI
{
    public class TaskNotice : MonoBehaviour
    {
        [SerializeField]
        private TextMeshProUGUI name;

        [SerializeField]
        private TextMeshProUGUI description;

        [SerializeField]
        private TextMeshProUGUI data;

        [SerializeField]
        private TextMeshProUGUI limitTime;

        [Header("动画设置")]
        [SerializeField]
        private float animationDuration = 0.5f; // 动画持续时间

        [SerializeField]
        private float moveDistance = 200f; // 移动距离

        [SerializeField]
        private Ease easeType = Ease.OutQuad; // 缓动类型

        private CanvasGroup canvasGroup; // 用于控制透明度
        private RectTransform rectTransform; // 用于控制位置
        private Vector2 originalPosition; // 记录初始位置
        private Tween currentTween; // 当前正在播放的动画

        void Awake()
        {
            // 自动查找未绑定的 TextMeshPro 引用
            var texts = GetComponentsInChildren<TextMeshProUGUI>(true);
            if (this.name == null && texts.Length > 0) this.name = texts[0];
            if (description == null && texts.Length > 1) description = texts[1];
            if (data == null && texts.Length > 2) data = texts[2];
            if (limitTime == null && texts.Length > 3) limitTime = texts[3];

            // 获取或添加 CanvasGroup 组件
            canvasGroup = GetComponent<CanvasGroup>();
            if (canvasGroup == null)
                canvasGroup = gameObject.AddComponent<CanvasGroup>();

            // 获取 RectTransform
            rectTransform = GetComponent<RectTransform>();
            if (rectTransform == null)
            {
                Debug.LogError("TaskNotice 需要挂载在带有 RectTransform 的 UI 对象上！");
                return;
            }

            // 记录初始位置
            originalPosition = rectTransform.anchoredPosition;
        }

        void Start() { }

        void Update() { }

        public void SetInfo(string name, string description, int limitTime, int requireCount)
        {
            if (this.name != null) this.name.text = name;
            if (this.description != null) this.description.text = description;
            if (this.limitTime != null) this.limitTime.text = "剩余时间：" + limitTime.ToString();
            if (this.data != null) this.data.text = $"{0}/{requireCount}";
        }

        public void Notice_Data(string data)
        {
            if (this.data != null) this.data.text = data;
        }

        private void OnEnable() { }

        private void OnDisable()
        {
            // 停止动画防止报错
            KillTween();
        }

        public void UpDateTime(string time)
        {
            if (limitTime != null) limitTime.text = time;
        }

        /// <summary>
        /// 播放文字滑入/滑出动画
        /// </summary>
        /// <param name="slideIn">true = 从右往左滑入（逐渐显示），false = 从左往右滑出（逐渐隐藏）</param>
        public void PlaySlideAnimation(bool slideIn)
        {
            // 停止当前正在播放的动画
            KillTween();

            // 组件未初始化完成则不播放
            if (rectTransform == null || canvasGroup == null)
                return;

            // 设置初始状态
            if (slideIn)
            {
                // 滑入：从左边开始，透明
                rectTransform.anchoredPosition = originalPosition - new Vector2(moveDistance, 0);
                canvasGroup.alpha = 0f;
                gameObject.SetActive(true);

                // 向右移动到原位 + 逐渐显示
                Sequence sequence = DOTween.Sequence();
                sequence.Join(
                    rectTransform.DOAnchorPos(originalPosition, animationDuration).SetEase(easeType)
                );
                sequence.Join(canvasGroup.DOFade(1f, animationDuration).SetEase(easeType));
                currentTween = sequence;
            }
            else
            {
                // 滑出：从原位向左移动 + 逐渐隐藏
                Sequence sequence = DOTween.Sequence();
                sequence.Join(
                    rectTransform
                        .DOAnchorPos(originalPosition - new Vector2(moveDistance, 0), animationDuration)
                        .SetEase(easeType)
                );
                sequence.Join(canvasGroup.DOFade(0f, animationDuration).SetEase(easeType));
                sequence.OnComplete(() =>
                {
                    gameObject.SetActive(false);
                });
                currentTween = sequence;
            }
        }

        /// <summary>
        /// 停止当前动画
        /// </summary>
        private void KillTween()
        {
            if (currentTween != null && currentTween.IsActive())
            {
                currentTween.Kill();
                currentTween = null;
            }
        }

        /// <summary>
        /// 带回调的动画播放
        /// </summary>
        /// <param name="slideIn">true = 从右往左滑入，false = 从左往右滑出</param>
        /// <param name="onComplete">动画完成回调</param>
        public void PlaySlideAnimation(bool slideIn, Action onComplete)
        {
            KillTween();

            if (slideIn)
            {
                rectTransform.anchoredPosition = originalPosition + new Vector2(moveDistance, 0);
                canvasGroup.alpha = 0f;
                gameObject.SetActive(true);

                Sequence sequence = DOTween.Sequence();
                sequence.Join(
                    rectTransform.DOAnchorPos(originalPosition, animationDuration).SetEase(easeType)
                );
                sequence.Join(canvasGroup.DOFade(1f, animationDuration).SetEase(easeType));
                sequence.OnComplete(() => onComplete?.Invoke());
                currentTween = sequence;
            }
            else
            {
                Sequence sequence = DOTween.Sequence();
                sequence.Join(
                    rectTransform
                        .DOAnchorPos(originalPosition + new Vector2(moveDistance, 0), animationDuration)
                        .SetEase(easeType)
                );
                sequence.Join(canvasGroup.DOFade(0f, animationDuration).SetEase(easeType));
                sequence.OnComplete(() =>
                {
                    gameObject.SetActive(false);
                    onComplete?.Invoke();
                });
                currentTween = sequence;
            }
        }
    }
}

using System.Collections.Generic;
using Core;
using UnityEngine;

namespace Managers
{
    /// <summary>
    /// 结算结果：打开任务面板时由 SettlePendingProgress 返回，
    /// 供 UI 层驱动平滑过渡动画。
    /// </summary>
    public class QuestSettleResult
    {
        /// <summary>结算前保存的旧进度（基准值）</summary>
        public Dictionary<int, int> oldProgress;
        /// <summary>本局新增的进度（delta，用于驱动动画）</summary>
        public Dictionary<int, int> delta;
    }

    /// <summary>
    /// 任务进度管理器 — 对局中记录事件，对局结束时缓存，打开面板时合并。
    ///
    /// 职责：
    /// - 对局中通过 RecordKill / RecordDamage 等记录事件
    /// - 打开任务面板时由 MassionPanel 调用 SettlePendingProgress()
    ///   → 将本次进度合并到累计进度 → 存档 → 返回 delta 供动画
    /// - 对局中只暂存在 pendingProgress，面板打开后才写入磁盘
    /// - 面板打开时从磁盘读取最新进度并播放平滑过渡动画
    /// </summary>
    public class QuestTaskManager : MonoBehaviour
    {
        public static QuestTaskManager Instance { get; private set; }

        // 对局中暂存的进度（taskId → 本次累加次数）
        private Dictionary<int, int> pendingProgress = new Dictionary<int, int>();

        // 跨对局累计进度（由 SaveManager 统一读写，替代 QuestTaskInventory）
        private Dictionary<int, int> cumulativeProgress = new Dictionary<int, int>();

        // 任务数据库
        private QuestTaskDatabaseSO taskDatabase;

        // ──────────────────────────────────
        //  单例生命周期
        // ──────────────────────────────────

        void Awake()
        {
            if (Instance == null)
            {
                Instance = this;
                DontDestroyOnLoad(gameObject);
            }
            else
            {
                Destroy(gameObject);
            }
        }

        void Start()
        {
            taskDatabase = Resources.Load<QuestTaskDatabaseSO>("QuestTask/QuestTaskDatabase");
            if (taskDatabase == null)
                Debug.LogWarning("[QuestTaskManager] 未找到 QuestTaskDatabase，请在 Resources/QuestTask/ 目录下创建");
        }

        // ──────────────────────────────────
        //  对局中记录（由其他系统调用）
        // ──────────────────────────────────

        /// <summary>记录一次击杀</summary>
        public void RecordKill() => AddProgress(QuestTaskType.KillEnemy);

        /// <summary>记录伤害（每100点伤害计1次）</summary>
        public void RecordDamage(int damageAmount)
        {
            // 按每100伤害为单位累加，避免数值过大
            int count = Mathf.Max(1, damageAmount / 100);
            for (int i = 0; i < count; i++)
                AddProgress(QuestTaskType.DealDamage);
        }

        /// <summary>记录一次金币获得</summary>
        public void RecordCoin() => AddProgress(QuestTaskType.CollectCoin);

        /// <summary>记录一次经验获得</summary>
        public void RecordExp() => AddProgress(QuestTaskType.CollectExp);

        /// <summary>记录完成一局</summary>
        public void RecordMatchComplete() => AddProgress(QuestTaskType.CompleteMatch);

        private void AddProgress(QuestTaskType type)
        {
            if (taskDatabase == null || taskDatabase.allTasks == null)
            {
                Debug.LogWarning($"[QuestTaskManager] AddProgress({type}) 跳过：taskDatabase={taskDatabase == null}");
                return;
            }

            int matched = 0;
            foreach (var task in taskDatabase.allTasks)
            {
                if (task != null && task.taskType == type)
                {
                    if (!pendingProgress.ContainsKey(task.taskId))
                        pendingProgress[task.taskId] = 0;
                    pendingProgress[task.taskId]++;
                    matched++;
                }
            }
            Debug.Log($"[QuestTaskManager] AddProgress({type}) 匹配 {matched} 个任务，pendingProgress 当前共 {pendingProgress.Count} 个条目");
        }

        // ──────────────────────────────────
        //  局外结算（由 MassionPanel 打开时调用）
        // ──────────────────────────────────

        /// <summary>
        /// 打开任务面板时调用：合并 pendingProgress → cumulativeProgress，
        /// 保存存档，返回旧进度和 delta 供 UI 驱动平滑动画。
        /// </summary>
        public QuestSettleResult SettlePendingProgress()
        {
            Debug.Log($"[QuestTaskManager] SettlePendingProgress：pending 共 {pendingProgress.Count} 项，cumulative 共 {cumulativeProgress.Count} 项");

            // 1. 快照旧进度（结算前的存档值）
            var oldSnapshot = new Dictionary<int, int>(cumulativeProgress);

            // 2. 合并本局新增进度
            var delta = new Dictionary<int, int>();
            foreach (var kvp in pendingProgress)
            {
                int taskId = kvp.Key;
                int added = kvp.Value;

                if (cumulativeProgress.ContainsKey(taskId))
                    cumulativeProgress[taskId] += added;
                else
                    cumulativeProgress[taskId] = added;

                delta[taskId] = added;

                Debug.Log($"[QuestTaskManager] 任务 {taskId} 进度 +{added}，当前累计 {cumulativeProgress[taskId]}");
            }

            // 3. 存入磁盘
            if (SaveManager.Instance != null)
                SaveManager.Instance.SaveGame();

            // 4. 清空暂存
            pendingProgress.Clear();

            return new QuestSettleResult
            {
                oldProgress = oldSnapshot,
                delta = delta
            };
        }

        // ──────────────────────────────────
        //  对局开始/结束
        // ──────────────────────────────────

        /// <summary>新对局开始时调用，清空暂存进度</summary>
        public void ResetPendingProgress()
        {
            pendingProgress.Clear();
        }

        /// <summary>获取所有任务的累计进度（给 SaveManager 存档时调用）</summary>
        public Dictionary<int, int> GetAllProgress()
        {
            return cumulativeProgress;
        }

        #region 公共方法
        /// <summary>
        /// 从存档恢复所有任务进度（由 SaveManager 读档时调用）
        /// </summary>
        public void SetAllProgress(Dictionary<int, int> progress)
        {
            cumulativeProgress.Clear();
            if (progress == null) return;

            foreach (var kvp in progress)
            {
                cumulativeProgress[kvp.Key] = kvp.Value;
            }

            Debug.Log($"[QuestTaskManager] 从存档恢复 {cumulativeProgress.Count} 个任务进度");
        }
        #endregion
    }
}

using System.Collections;
using System.Collections.Generic;
using Core;
using Core.Channels.Combat;
using Core.Channels.Player;
using Core.Channels.Task;
using Controllers.Services;
using NetworkTarget = Controllers.Network.NetworkTarget;
using Controllers.Task;
using Controllers.Network;
using UI;
using Unity.VisualScripting;
using UnityEngine;

namespace Managers
{
    public class TaskManager : MonoBehaviour
    {
        #region 单例模式
        public static TaskManager instance;
        public static TaskManager Instance => instance;

        void Awake()
        {
            if (instance == null)
            {
                instance = this;
            }
            else
            {
                Destroy(gameObject);
            }
        }
        #endregion

        [Header("可视化设置")]
        [SerializeField]
        private bool showZoneGizmos = true;

        private GameObject taskZone;

        [SerializeField]
        private Color gizmoColor = new Color(0, 1, 0, 0.3f);

        private Dictionary<string, TaskBase> tasks = new Dictionary<string, TaskBase>();

        private HashSet<int> reportedEnemies = new HashSet<int>();

        private int countdownTime = 0;
        private int taskDuration;
        private Coroutine taskRoutine;

        public event System.Action<TaskBase> OnTaskUpdated;
        public event System.Action<TaskBase> OnTaskCompleted;

        private void OnEnable()
        {
            OnTaskCompleted += OnTaskCompletedFun;
            EventChannelLocator.MainContainer.taskNoticeChannel.RegisterListener(OnTaskNoticeReceived);
            EventChannelLocator.MainContainer.enemyReportChannel.RegisterListener(OnEnemyReported);
            EventChannelLocator.MainContainer.taskActivationChannel.RegisterListener(OnTaskActivationReceived);
        }

        private void OnDisable()
        {
            OnTaskCompleted -= OnTaskCompletedFun;
            EventChannelLocator.MainContainer.taskNoticeChannel.UnregisterListener(OnTaskNoticeReceived);
            EventChannelLocator.MainContainer.enemyReportChannel.UnregisterListener(OnEnemyReported);
            EventChannelLocator.MainContainer.taskActivationChannel.UnregisterListener(OnTaskActivationReceived);
        }

        private void OnEnemyReported(EnemyReportData data)
        {
            if (data == null) return;
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "RPC_ReportCount", NetworkTarget.MasterClient, data.position, data.networkViewID);
        }

        private void OnTaskNoticeReceived(TaskNoticeData data)
        {
            if (data == null) return;
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "RPC_SetNotice", NetworkTarget.All, data.name, data.description, data.limitTime, data.requiredCount);
        }

        /// <summary>
        /// 收到 taskActivationChannel 事件 → 分发到 ActivateTask
        /// </summary>
        private void OnTaskActivationReceived(TaskBase task)
        {
            if (task == null) return;
            ActivateTask(task);
        }

        public void SetNotice(string name, string description, int limitTime, int requeredCount = 1)
        {
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "RPC_SetNotice", NetworkTarget.All, name, description, limitTime, requeredCount);
        }

        private void StartCountdownTime(int time)
        {
            countdownTime = time;

            if (taskRoutine != null)
            {
                StopCoroutine(taskRoutine);
            }

            taskRoutine = StartCoroutine(TaskRoutine());
        }

        IEnumerator TaskRoutine()
        {
            string time = "";
            while (countdownTime > 0)
            {
                yield return new WaitForSeconds(1f);
                countdownTime--;
                int min = Mathf.FloorToInt(countdownTime / 60);
                int sec = Mathf.FloorToInt(countdownTime % 60);
                time = "剩余时间：" + $"{min:D2}:{sec:D2}";
                NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "RPC_UpdateAllPlayerTimeUI", NetworkTarget.All, time);
            }
            Debug.LogWarning("任务失败");
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "RPC_TaskFailed", NetworkTarget.All);
            yield break;
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：更新所有玩家的任务时间 UI
        /// </summary>
        public static void HandleUpdateAllPlayerTimeUIRPC(string time)
        {
            EventChannelLocator.MainContainer.taskUIChannel.Raise(TaskUIUpdateData.UpdateTime(time));
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：任务失败
        /// </summary>
        public static void HandleTaskFailedRPC()
        {
            if (Instance == null) return;
            if (Instance.taskZone == null) return;
            Destroy(Instance.taskZone.gameObject);
            Instance.taskZone = null;
            EventChannelLocator.MainContainer.taskUIChannel.Raise(TaskUIUpdateData.ClearIndicator());
            EventChannelLocator.MainContainer.taskUIChannel.Raise(TaskUIUpdateData.HideNotice());
        }

        void Notice_Data(string data)
        {
            EventChannelLocator.MainContainer.taskUIChannel.Raise(TaskUIUpdateData.NoticeData(data));
        }

        public void ActivateTask(TaskBase taskBase)
        {
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
                return;
            switch (taskBase)
            {
                case KillTask killTask:
                    NetworkServiceLocator.ObjectService.InvokeRPC(
                        AppRpcBridge.Instance,
                        "RPC_ActivateKillTask",
                        NetworkTarget.All,
                        killTask.TaskId,
                        killTask.limitTime,
                        killTask.ZoneCenter,
                        killTask.RequiredKills
                    );
                    break;
                case EscortTask escortTask:
                    NetworkServiceLocator.ObjectService.InvokeRPC(
                        AppRpcBridge.Instance,
                        "RPC_ActivateEscortTask",
                        NetworkTarget.All,
                        escortTask.TaskId,
                        escortTask.limitTime,
                        escortTask.ZoneCenter,
                        escortTask.requiredEscorts
                    );
                    break;
                default:
                    break;
            }
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：激活击杀任务
        /// </summary>
        public static void HandleActivateKillTaskRPC(string taskId, int limitTime, Vector3 zoneCenter, int requiredKills)
        {
            if (Instance == null) return;

            if (NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                Instance.StartCountdownTime(limitTime);
            }
            Instance.taskZone = Instantiate(
                Resources.Load<GameObject>("TaskPrefab/" + taskId),
                zoneCenter,
                Quaternion.identity
            );
            Instance.tasks.Clear();

            KillTask killTask = new KillTask(taskId, zoneCenter, 7, requiredKills, limitTime);
            Instance.tasks[taskId] = killTask;

            Debug.Log($"任务{taskId}已激活，中心位置：{zoneCenter}" + Instance.taskZone.name);
            EventChannelLocator.MainContainer.taskUIChannel.Raise(
                TaskUIUpdateData.SetIndicator(zoneCenter, taskId));
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：激活护送任务
        /// </summary>
        public static void HandleActivateEscortTaskRPC(
            string taskId,
            int limitTime,
            Vector3 zoneCenter,
            int requiredEscorts
        )
        {
            if (Instance == null) return;

            if (NetworkServiceLocator.PlayerService.IsMasterClient)
            {
                Instance.StartCountdownTime(limitTime);
            }
            Instance.taskZone = Instantiate(
                Resources.Load<GameObject>("TaskPrefab/" + taskId),
                zoneCenter,
                Quaternion.identity
            );
            Instance.tasks.Clear();
            EscortTask escortTask = new EscortTask(taskId, zoneCenter, 4, requiredEscorts, limitTime);
            Instance.tasks[escortTask.TaskId] = escortTask;
            Debug.Log($"任务{taskId}已激活，中心位置：{zoneCenter}" + Instance.taskZone.name);
            EventChannelLocator.MainContainer.taskUIChannel.Raise(
                TaskUIUpdateData.SetIndicator(zoneCenter, taskId));
        }

        public void ReportCount(Vector3 killPosition, int enemyViewID)
        {
            NetworkServiceLocator.ObjectService.InvokeRPC(AppRpcBridge.Instance, "RPC_ReportCount", NetworkTarget.MasterClient, killPosition, enemyViewID);
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：上报击杀计数
        /// </summary>
        public static void HandleReportCountRPC(Vector3 killPosition, int enemyViewID)
        {
            if (Instance == null) return;
            if (!NetworkServiceLocator.PlayerService.IsMasterClient)
                return;

            if (Instance.reportedEnemies.Contains(enemyViewID))
            {
                return;
            }

            foreach (var task in Instance.tasks.Values)
            {
                if (task.IsCompleted)
                    continue;

                if (task is KillTask killTask)
                {
                    KillTask kt = task as KillTask;
                    if (Vector3.Distance(killPosition, task.ZoneCenter) <= task.ZoneRadius)
                    {
                        kt.CurrentKills++;
                        Instance.reportedEnemies.Add(enemyViewID);
                        Debug.LogWarning(
                            $"任务{task.TaskId}击 增加1," + $"当前击杀次数：{kt.CurrentKills}"
                        );
                        if (kt.CurrentKills >= kt.RequiredKills)
                        {
                            task.IsCompleted = true;
                        }
                        NetworkServiceLocator.ObjectService.InvokeRPC(
                            AppRpcBridge.Instance,
                            "RPC_UpdateProgress",
                            NetworkTarget.All,
                            task.TaskId,
                            kt.CurrentKills,
                            task.IsCompleted
                        );

                        break;
                    }
                }

                if (task is EscortTask escortTask)
                {
                    if (Vector3.Distance(killPosition, task.ZoneCenter) <= task.ZoneRadius)
                    {
                        escortTask.currentEscorts++;
                        Instance.reportedEnemies.Add(enemyViewID);
                        Debug.LogWarning(
                            $"任务{task.TaskId}击 增加1,"
                                + $"当前运输机器人：{escortTask.currentEscorts}"
                        );
                        if (escortTask.currentEscorts >= escortTask.requiredEscorts)
                        {
                            escortTask.IsCompleted = true;
                        }
                        NetworkServiceLocator.ObjectService.InvokeRPC(
                            AppRpcBridge.Instance,
                            "RPC_UpdateProgress",
                            NetworkTarget.All,
                            task.TaskId,
                            escortTask.currentEscorts,
                            task.IsCompleted
                        );

                        break;
                    }
                }
            }
        }

        /// <summary>
        /// 由 AppRpcBridge 在收到 RPC 后调用：更新任务进度
        /// </summary>
        public static void HandleUpdateProgressRPC(string taskId, int count, bool completed)
        {
            if (Instance == null) return;

            if (Instance.tasks.TryGetValue(taskId, out var task))
            {
                switch (task)
                {
                    case KillTask killTask:
                        killTask.CurrentKills = count;
                        killTask.IsCompleted = completed;
                        Instance.OnTaskUpdated?.Invoke(task);
                        Instance.Notice_Data($"{count}/{killTask.RequiredKills}");
                        break;
                    case EscortTask escortTask:
                        escortTask.currentEscorts = count;
                        escortTask.IsCompleted = completed;
                        Instance.OnTaskUpdated?.Invoke(task);
                        Instance.Notice_Data($"{count}/{escortTask.requiredEscorts}");
                        break;
                }

                if (completed)
                    Instance.OnTaskCompleted?.Invoke(task);
            }
        }

        void OnTaskCompletedFun(TaskBase task)
        {
            EventChannelLocator.MainContainer.taskUIChannel.Raise(TaskUIUpdateData.ClearIndicator());
            switch (task)
            {
                case KillTask killTask:
                    Notice_Data($"击杀任务完成！");
                    StartCoroutine(DelayReward(0.5f));
                    break;
                case EscortTask escortTask:
                    Notice_Data($"护送任务完成！");
                    StartCoroutine(DelayReward(12f));
                    break;
            }
        }

        IEnumerator DelayReward(float delay)
        {
            yield return new WaitForSeconds(delay);
            EventChannelLocator.MainContainer.taskUIChannel.Raise(TaskUIUpdateData.HideNotice());
            Destroy(taskZone.gameObject);
            if (taskRoutine != null)
            {
                StopCoroutine(taskRoutine);
            }
            taskZone = null;
            // 标记：本次卡牌选择必定为 3 张英雄专属强化
            if (MagicUpgradeManager.instance != null)
                MagicUpgradeManager.instance.isAllExCard = true;
            EventChannelLocator.MainContainer.magicUpgradeChannel.Raise(true);
            var expQuery = new SkillQueryData(SkillQueryType.GetUpgradeExperience);
            EventChannelLocator.MainContainer.skillQueryChannel.Raise(expQuery);
            EventChannelLocator.MainContainer.experienceChannel.Raise(expQuery.intValue);
        }

        void OnDrawGizmos()
        {
            if (!showZoneGizmos)
                return;

            foreach (var task in tasks.Values)
            {
                if (task.IsCompleted)
                    Gizmos.color = new Color(1, 1, 0, 0.3f);
                else
                    Gizmos.color = gizmoColor;

                Gizmos.DrawWireSphere(task.ZoneCenter, task.ZoneRadius);
                Gizmos.DrawSphere(task.ZoneCenter, 0.3f);
            }
        }
    }

    public enum TaskType
    {
        Kill,
        Escort,
    }

    public class TaskConst
    {
        public const string KillSacrifice = "KillSacrifice";
    }
}

using System.Collections;
using System.Collections.Generic;
using Core;
using Core;
using Controllers;
using UnityEngine;
using UnityEngine.Audio;

namespace Managers
{
    /// <summary>
    /// 音频管理器 — 核心控制器
    /// 职责：BGM 播放/切换/交叉淡入淡出、SFX/UI 音效播放、环境音播放、
    ///       音量管理（AudioMixer 集成）、暂停恢复
    /// 生命周期：懒加载单例，DontDestroyOnLoad 跨场景
    /// </summary>
    public class AudioManager : MonoBehaviour
    {
        /* ==================== 单例 ==================== */

        private static AudioManager _instance;

        public static AudioManager Instance
        {
            get
            {
                if (_instance == null)
                {
                    var go = new GameObject("[AudioManager]");
                    _instance = go.AddComponent<AudioManager>();
                    DontDestroyOnLoad(go);
                }
                return _instance;
            }
        }

        /* ==================== Inspector 配置 ==================== */

        [Header("配置资源")]
        [SerializeField] private SoundLibrarySO _soundLibrary;
        [SerializeField] private AudioConfigSO _config;
        [SerializeField] private AudioMixer _audioMixer;

        /* ==================== 运行时组件 ==================== */

        // ——— BGM（双源交叉淡入淡出） ———
        private AudioSource _bgmSource;          // 主 BGM 通道
        private AudioSource _bgmSource2;         // 辅 BGM 通道（用于交叉淡入淡出）

        // ——— 环境音 ———
        private AudioSource _ambientSource;      // 环境音专用通道

        // ——— SFX 对象池 ———
        private AudioSourcePool _sfxPool;

        // ——— Mixer 控制器 ———
        private AudioMixerController _mixerController;

        /* ==================== 运行时状态 ==================== */

        private string _currentBGMId;              // 当前 BGM 的 soundId
        private Coroutine _bgmFadeJob;             // BGM 淡入淡出协程
        private float _masterVolume = 1f;          // 总音量（回退值）
        private Dictionary<AudioChannelType, float> _volumes;  // 各类型音量（回退值）
        private bool _useMixer;                    // 是否正在使用 AudioMixer

        // ——— BGM Ducking ———
        private Coroutine _duckJob;                 // Ducking 协程
        private float _bgmVolumeBeforeDuck = 1f;    // Ducking 前的 BGM 音量

        // ——— 卡牌选择面板激活时跳过音频暂停 ———
        private bool _skipAudioPause;

        /* ==================== PlayerPrefs 持久化键 ==================== */

        private const string PREF_MASTER = "Audio_Master";
        private const string PREF_BGM = "Audio_BGM";
        private const string PREF_SFX = "Audio_SFX";
        private const string PREF_UI = "Audio_UI";
        private const string PREF_AMBIENT = "Audio_Ambient";

        /* ==================== 初始化 ==================== */

        private void Awake()
        {
            if (_instance != null && _instance != this)
            {
                Destroy(gameObject);
                return;
            }

            _instance = this;
            ServiceLocator.Register(this);
            DontDestroyOnLoad(gameObject);
            Initialize();
        }

        private void Initialize()
        {
            // 从 Resources 加载配置（如果 Inspector 未赋值）
            if (_config == null)
                _config = Resources.Load<AudioConfigSO>("Audio/Config/AudioConfig");

            if (_soundLibrary == null)
                _soundLibrary = Resources.Load<SoundLibrarySO>("Audio/Libraries/MainSoundLibrary");

            Debug.Log($"[AudioManager] 初始化: _soundLibrary={(_soundLibrary != null ? _soundLibrary.name : "NULL")}, _config={(_config != null ? _config.name : "NULL")}, _audioMixer={(_audioMixer != null ? _audioMixer.name : "NULL")}");

            if (_audioMixer == null)
                _audioMixer = Resources.Load<AudioMixer>("Audio/MainMixer");

            // ——— 初始化 AudioMixer 控制器 ———
            _mixerController = new AudioMixerController(_audioMixer);
            _useMixer = _mixerController.IsValid;

            if (_useMixer)
                Debug.Log("[AudioManager] AudioMixer 已加载，音量将通过 Mixer 控制");
            else
                Debug.Log("[AudioManager] 未找到 AudioMixer，将回退为直接控制 AudioSource.volume");

            // ——— 创建 BGM 双通道 ———
            _bgmSource = CreateAudioSource("BGM_Primary", AudioChannelType.BGM, true);
            _bgmSource2 = CreateAudioSource("BGM_Secondary", AudioChannelType.BGM, true);

            // ——— 创建环境音通道 ———
            _ambientSource = CreateAudioSource("Ambient", AudioChannelType.Ambient, true);

            // ——— 创建 SFX 对象池 ———
            int poolSize = _config != null ? _config.poolSize : 20;
            bool autoExpand = _config != null ? _config.poolAutoExpand : true;
            AudioMixerGroup sfxGroup = _useMixer ? _mixerController.GetGroup(AudioChannelType.SFX) : null;
            _sfxPool = new AudioSourcePool(poolSize, autoExpand, transform, sfxGroup);

            // ——— 初始化音量 ———
            _masterVolume = PlayerPrefs.GetFloat(PREF_MASTER, _config != null ? _config.masterVolume : 1f);
            _volumes = new Dictionary<AudioChannelType, float>
            {
                [AudioChannelType.BGM] = PlayerPrefs.GetFloat(PREF_BGM, _config != null ? _config.bgmVolume : 1f),
                [AudioChannelType.SFX] = PlayerPrefs.GetFloat(PREF_SFX, _config != null ? _config.sfxVolume : 1f),
                [AudioChannelType.UI] = PlayerPrefs.GetFloat(PREF_UI, _config != null ? _config.uiVolume : 1f),
                [AudioChannelType.Ambient] = PlayerPrefs.GetFloat(PREF_AMBIENT, _config != null ? _config.ambientVolume : 1f),
            };

            // 同步到 Mixer
            if (_useMixer)
            {
                _mixerController.SetMasterVolume(_masterVolume);
                _mixerController.SetGroupVolume(AudioChannelType.BGM, _volumes[AudioChannelType.BGM]);
                _mixerController.SetGroupVolume(AudioChannelType.SFX, _volumes[AudioChannelType.SFX]);
                _mixerController.SetGroupVolume(AudioChannelType.UI, _volumes[AudioChannelType.UI]);
                _mixerController.SetGroupVolume(AudioChannelType.Ambient, _volumes[AudioChannelType.Ambient]);
            }

            Debug.Log("[AudioManager] 初始化完成" + (_useMixer ? "（AudioMixer 模式）" : "（基础模式）"));
        }

        /// <summary>创建并配置一个 AudioSource，自动分配到对应的 Mixer Group</summary>
        private AudioSource CreateAudioSource(string name, AudioChannelType AudioChannelType, bool loop)
        {
            var go = new GameObject(name);
            go.transform.SetParent(transform);

            var source = go.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.loop = loop;

            // 分配到 Mixer Group
            if (_useMixer)
            {
                var group = _mixerController.GetGroup(AudioChannelType);
                if (group != null)
                    source.outputAudioMixerGroup = group;
            }

            return source;
        }

        private void OnEnable()
        {
            EventChannelLocator.MainContainer.pauseStateChannel?.RegisterListener(OnPauseStateChanged);
            EventChannelLocator.MainContainer.magicUpgradeChannel?.RegisterListener(OnMagicUpgradeRequested);
        }

        private void OnDisable()
        {
            EventChannelLocator.MainContainer.pauseStateChannel?.UnregisterListener(OnPauseStateChanged);
            EventChannelLocator.MainContainer.magicUpgradeChannel?.UnregisterListener(OnMagicUpgradeRequested);
        }

        private void OnMagicUpgradeRequested(bool isOpen)
        {
            _skipAudioPause = isOpen;
        }

        private void OnPauseStateChanged(bool isPaused)
        {
            if (_skipAudioPause)
                return;

            if (isPaused)
                PauseAll();
            else
                ResumeAll();
        }

        /* ==================== BGM 管理 ==================== */

        /// <summary>播放背景音乐（自动处理交叉淡入淡出切换）</summary>
        /// <param name="soundId">BGM 音效定义 ID</param>
        /// <param name="fadeDuration">淡入淡出时长（秒），默认使用配置值</param>
        public void PlayBGM(string soundId, float? fadeDuration = null)
        {
            if (string.IsNullOrEmpty(soundId))
            {
                Debug.LogWarning("[AudioManager] PlayBGM: soundId 为空");
                return;
            }

            if (soundId == _currentBGMId)
                return;

            if (!_soundLibrary.TryGetSound(soundId, out var def))
            {
                Debug.LogError($"[AudioManager] 未找到 BGM 定义: {soundId}");
                return;
            }

            _currentBGMId = soundId;

            if (_bgmFadeJob != null)
                StopCoroutine(_bgmFadeJob);

            _bgmFadeJob = StartCoroutine(PlayBGMInternal(def, fadeDuration));
        }

        /// <summary>
        /// BGM 播放协程 — 使用双 AudioSource 实现真正的同步交叉淡入淡出
        /// 旧 BGM 在新 BGM 开始播放的同时淡出，保证音乐无缝衔接
        /// </summary>
        private IEnumerator PlayBGMInternal(SoundDefinitionSO def, float? fadeDuration)
        {
            float duration = fadeDuration ?? (_config != null ? _config.bgmCrossfadeDuration : 1f);

            // 确定新旧两个源
            bool hasCurrent = _bgmSource.clip != null && _bgmSource.isPlaying;

            // 配置新源（始终使用 _bgmSource2 作为" incoming"）
            AudioSource incoming = _bgmSource2;
            AudioSource outgoing = hasCurrent ? _bgmSource : null;

            incoming.clip = def.clip;
            incoming.pitch = def.pitch;
            incoming.spatialBlend = 0f;
            incoming.volume = 0f;
            incoming.Play();

            // 同步交叉淡入淡出
            float targetVol = def.volume * (_useMixer ? 1f : GetFinalVolume(AudioChannelType.BGM));
            float startVol = hasCurrent ? outgoing.volume : 0f;
            float elapsed = 0f;

            while (elapsed < duration)
            {
                elapsed += Time.unscaledDeltaTime;
                float t = elapsed / duration;

                incoming.volume = Mathf.Lerp(0f, targetVol, t);

                if (hasCurrent && outgoing != null)
                    outgoing.volume = Mathf.Lerp(startVol, 0f, t);

                yield return null;
            }

            // 停止旧源
            if (hasCurrent && outgoing != null)
            {
                outgoing.Stop();
                outgoing.clip = null;
                outgoing.volume = 0f;
            }

            // 交换：新源成为主源，旧源变为备用
            _bgmSource = incoming;
            _bgmSource2 = outgoing ?? _bgmSource2; // 如果 outgoing 为 null，保留 _bgmSource2

            _bgmFadeJob = null;
        }

        /// <summary>停止背景音乐（淡出）</summary>
        /// <param name="fadeDuration">淡出时长（秒），默认使用配置值</param>
        public void StopBGM(float? fadeDuration = null)
        {
            if (_bgmFadeJob != null)
                StopCoroutine(_bgmFadeJob);

            _bgmFadeJob = StartCoroutine(StopBGMInternal(fadeDuration ?? (_config != null ? _config.bgmFadeOutDuration : 1f)));
        }

        private IEnumerator StopBGMInternal(float fadeOut)
        {
            AudioSource target = _bgmSource;

            if (target != null && target.isPlaying)
            {
                float startVol = target.volume;
                float elapsed = 0f;

                while (elapsed < fadeOut)
                {
                    elapsed += Time.unscaledDeltaTime;
                    target.volume = Mathf.Lerp(startVol, 0f, elapsed / fadeOut);
                    yield return null;
                }

                target.Stop();
                target.volume = 0f;
            }

            _currentBGMId = null;
            _bgmFadeJob = null;
        }

        /* ==================== SFX 管理 ==================== */

        /// <summary>播放 2D / 3D 音效</summary>
        /// <param name="soundId">音效 ID</param>
        /// <param name="position">3D 空间中的播放位置（null = 2D）</param>
        /// <param name="attachTarget">跟随的目标 Transform（不为 null 时忽略 position）</param>
        public void PlaySFX(string soundId, Vector3? position = null, Transform attachTarget = null)
        {
            if (!_soundLibrary.TryGetSound(soundId, out var def))
            {
                Debug.LogError($"[AudioManager] 未找到 SFX 定义: {soundId}");
                return;
            }

            var source = _sfxPool.Get();
            if (source == null)
            {
                Debug.LogWarning($"[AudioManager] SFX 对象池已满，无法播放: {soundId}");
                return;
            }

            source.clip = def.clip;
            source.volume = def.volume * (_useMixer ? 1f : GetFinalVolume(AudioChannelType.SFX));
            source.pitch = def.pitch;
            source.spatialBlend = attachTarget != null || position.HasValue ? 1f : def.spatialBlend;
            source.minDistance = def.minDistance;
            source.maxDistance = def.maxDistance;
            source.loop = false;

            if (attachTarget != null)
            {
                source.transform.SetParent(attachTarget);
                source.transform.localPosition = Vector3.zero;
            }
            else if (position.HasValue)
            {
                source.transform.position = position.Value;
            }

            source.Play();

            StartCoroutine(ReturnToPoolAfterPlay(source, def.clip != null ? def.clip.length + 0.1f : 0.5f));
        }

        private IEnumerator ReturnToPoolAfterPlay(AudioSource source, float delay)
        {
            yield return new WaitForSeconds(delay);

            if (source != null)
            {
                source.Stop();
                source.clip = null;
                source.transform.SetParent(transform);
                _sfxPool.Return(source);
            }
        }

        /* ==================== UI 音效 ==================== */

        /// <summary>播放 UI 音效（2D，不受空间音频影响）</summary>
        /// <param name="soundId">音效 ID</param>
        public void PlayUI(string soundId)
        {
            if (!_soundLibrary.TryGetSound(soundId, out var def))
            {
                Debug.LogError($"[AudioManager] 未找到 UI 音效定义: {soundId}");
                return;
            }

            var source = _sfxPool.Get();
            if (source == null)
            {
                Debug.LogWarning($"[AudioManager] SFX 对象池已满，无法播放 UI 音效: {soundId}");
                return;
            }

            source.clip = def.clip;
            source.volume = def.volume * (_useMixer ? 1f : GetFinalVolume(AudioChannelType.UI));
            source.pitch = def.pitch;
            source.spatialBlend = 0f;
            source.loop = false;
            source.Play();

            StartCoroutine(ReturnToPoolAfterPlay(source, def.clip != null ? def.clip.length + 0.1f : 0.5f));
        }

        /* ==================== 环境音 ==================== */

        /// <summary>播放环境音（循环，可设置 3D 位置）</summary>
        /// <param name="soundId">环境音音效 ID</param>
        /// <param name="position">3D 空间位置（null = 2D 环境音）</param>
        public void PlayAmbient(string soundId, Vector3? position = null)
        {
            if (string.IsNullOrEmpty(soundId))
            {
                Debug.LogWarning("[AudioManager] PlayAmbient: soundId 为空");
                return;
            }

            if (!_soundLibrary.TryGetSound(soundId, out var def))
            {
                Debug.LogError($"[AudioManager] 未找到 Ambient 定义: {soundId}");
                return;
            }

            _ambientSource.clip = def.clip;
            _ambientSource.volume = def.volume * (_useMixer ? 1f : GetFinalVolume(AudioChannelType.Ambient));
            _ambientSource.pitch = def.pitch;
            _ambientSource.spatialBlend = position.HasValue ? 1f : def.spatialBlend;
            _ambientSource.minDistance = def.minDistance;
            _ambientSource.maxDistance = def.maxDistance;
            _ambientSource.loop = true;

            if (position.HasValue)
                _ambientSource.transform.position = position.Value;

            _ambientSource.Play();
        }

        /// <summary>停止环境音</summary>
        public void StopAmbient()
        {
            if (_ambientSource != null && _ambientSource.isPlaying)
            {
                _ambientSource.Stop();
            }
        }

        /* ==================== BGM Ducking（音量闪避） ==================== */

        /// <summary>
        /// 临时降低 BGM 音量（Ducking），用于重要音效/语音播放时避免冲突
        /// 例如：Boss 吼叫、剧情对话时自动闪避背景音乐
        /// </summary>
        /// <param name="targetVolume">目标音量 (0~1)，默认 0.2</param>
        /// <param name="fadeDuration">淡入淡出时长（秒），默认 0.3</param>
        public void DuckBGM(float targetVolume = 0.2f, float fadeDuration = 0.3f)
        {
            if (_duckJob != null)
                StopCoroutine(_duckJob);

            _duckJob = StartCoroutine(DuckBGMInternal(targetVolume, fadeDuration));
        }

        /// <summary>恢复 BGM 音量到 Ducking 之前的值</summary>
        /// <param name="fadeDuration">恢复时长（秒），默认 1.0</param>
        public void UnduckBGM(float fadeDuration = 1f)
        {
            if (_duckJob != null)
                StopCoroutine(_duckJob);

            _duckJob = StartCoroutine(UnduckBGMInternal(fadeDuration));
        }

        private IEnumerator DuckBGMInternal(float targetVolume, float fadeDuration)
        {
            AudioSource target = _bgmSource;
            if (target == null || !target.isPlaying)
            {
                _duckJob = null;
                yield break;
            }

            _bgmVolumeBeforeDuck = target.volume;
            float startVol = target.volume;
            float elapsed = 0f;

            while (elapsed < fadeDuration)
            {
                elapsed += Time.unscaledDeltaTime;
                target.volume = Mathf.Lerp(startVol, targetVolume, elapsed / fadeDuration);
                yield return null;
            }

            target.volume = targetVolume;
            _duckJob = null;
        }

        private IEnumerator UnduckBGMInternal(float fadeDuration)
        {
            AudioSource target = _bgmSource;
            if (target == null || !target.isPlaying)
            {
                _duckJob = null;
                yield break;
            }

            float startVol = target.volume;
            float elapsed = 0f;

            while (elapsed < fadeDuration)
            {
                elapsed += Time.unscaledDeltaTime;
                target.volume = Mathf.Lerp(startVol, _bgmVolumeBeforeDuck, elapsed / fadeDuration);
                yield return null;
            }

            target.volume = _bgmVolumeBeforeDuck;
            _duckJob = null;
        }

        /* ==================== 音量管理 ==================== */

        /// <summary>设置总音量</summary>
        public void SetMasterVolume(float volume)
        {
            _masterVolume = Mathf.Clamp01(volume);

            if (_useMixer)
                _mixerController.SetMasterVolume(_masterVolume);
            else
                ApplyVolumeToActiveSources();

            PlayerPrefs.SetFloat(PREF_MASTER, _masterVolume);
            PlayerPrefs.Save();
        }

        /// <summary>设置指定类型的音量</summary>
        public void SetVolume(AudioChannelType type, float volume)
        {
            if (!_volumes.ContainsKey(type))
            {
                Debug.LogWarning($"[AudioManager] 不支持的音频类型: {type}");
                return;
            }

            _volumes[type] = Mathf.Clamp01(volume);

            // 通过 Mixer 控制（优先）或直接控制 AudioSource
            if (_useMixer)
                _mixerController.SetGroupVolume(type, _volumes[type]);
            else
                ApplyVolumeToActiveSources();

            // 持久化
            string key = type switch
            {
                AudioChannelType.BGM => PREF_BGM,
                AudioChannelType.SFX => PREF_SFX,
                AudioChannelType.UI => PREF_UI,
                AudioChannelType.Ambient => PREF_AMBIENT,
                _ => null,
            };

            if (key != null)
            {
                PlayerPrefs.SetFloat(key, _volumes[type]);
                PlayerPrefs.Save();
            }
        }

        /// <summary>获取总音量</summary>
        public float GetMasterVolume() => _useMixer ? _mixerController.GetMasterVolume() : _masterVolume;

        /// <summary>获取指定类型的音量</summary>
        public float GetVolume(AudioChannelType type) => _useMixer ? _mixerController.GetGroupVolume(type) : _volumes.GetValueOrDefault(type, 1f);

        /// <summary>计算最终播放音量（Master × 类型音量，仅非 Mixer 模式使用）</summary>
        private float GetFinalVolume(AudioChannelType type)
        {
            return _masterVolume * _volumes.GetValueOrDefault(type, 1f);
        }

        /// <summary>将当前音量设置应用到所有正在播放的 AudioSource（非 Mixer 模式回退方案）</summary>
        private void ApplyVolumeToActiveSources()
        {
            if (_bgmSource != null && _bgmSource.isPlaying)
                _bgmSource.volume = GetFinalVolume(AudioChannelType.BGM);

            _sfxPool?.ApplyVolume(GetFinalVolume(AudioChannelType.SFX));
        }

        /* ==================== 生命周期控制 ==================== */

        /// <summary>暂停所有音频</summary>
        public void PauseAll()
        {
            if (_bgmSource != null) _bgmSource.Pause();
            if (_ambientSource != null) _ambientSource.Pause();
            _sfxPool?.PauseAll();
        }

        /// <summary>恢复所有音频</summary>
        public void ResumeAll()
        {
            if (_bgmSource != null) _bgmSource.UnPause();
            if (_ambientSource != null) _ambientSource.UnPause();
            _sfxPool?.ResumeAll();
        }

        /// <summary>停止所有音频</summary>
        public void StopAll()
        {
            StopBGM(0f);
            StopAmbient();
            _sfxPool?.StopAll();
        }

        /* ==================== 内部类：AudioSource 对象池 ==================== */

        /// <summary>
        /// AudioSource 对象池 — 复用 AudioSource 实例，避免频繁创建/销毁
        /// </summary>
        private class AudioSourcePool
        {
            private AudioSource[] _pool;
            private readonly Queue<int> _available;
            private readonly Transform _root;
            private readonly bool _autoExpand;

            public AudioSourcePool(int size, bool autoExpand, Transform root, AudioMixerGroup mixerGroup)
            {
                _pool = new AudioSource[size];
                _available = new Queue<int>(size);
                _root = root;
                _autoExpand = autoExpand;

                for (int i = 0; i < size; i++)
                {
                    CreateSource(i, mixerGroup);
                    _available.Enqueue(i);
                }
            }

            private void CreateSource(int index, AudioMixerGroup mixerGroup)
            {
                var go = new GameObject($"SFX_Pool_{index}");
                go.transform.SetParent(_root);
                go.SetActive(false);

                var source = go.AddComponent<AudioSource>();
                source.playOnAwake = false;
                source.outputAudioMixerGroup = mixerGroup;
                _pool[index] = source;
            }

            public AudioSource Get()
            {
                if (_available.Count == 0)
                {
                    if (_autoExpand)
                    {
                        int newIndex = _pool.Length;
                        System.Array.Resize(ref _pool, newIndex + 1);
                        CreateSource(newIndex, null);
                        _pool[newIndex].gameObject.SetActive(true);
                        return _pool[newIndex];
                    }

                    return null;
                }

                int idx = _available.Dequeue();
                _pool[idx].gameObject.SetActive(true);
                return _pool[idx];
            }

            public void Return(AudioSource source)
            {
                for (int i = 0; i < _pool.Length; i++)
                {
                    if (_pool[i] == source)
                    {
                        source.gameObject.SetActive(false);
                        source.transform.SetParent(_root);
                        source.transform.localPosition = Vector3.zero;
                        _available.Enqueue(i);
                        return;
                    }
                }
            }

            public void ApplyVolume(float volume)
            {
                foreach (var source in _pool)
                {
                    if (source != null && source.isPlaying)
                        source.volume = volume;
                }
            }

            public void PauseAll()
            {
                foreach (var source in _pool)
                {
                    if (source != null && source.isPlaying)
                        source.Pause();
                }
            }

            public void ResumeAll()
            {
                foreach (var source in _pool)
                {
                    if (source != null && source.clip != null)
                        source.UnPause();
                }
            }

            public void StopAll()
            {
                foreach (var source in _pool)
                {
                    if (source != null && source.isPlaying)
                    {
                        source.Stop();
                        source.clip = null;
                        source.gameObject.SetActive(false);
                    }
                }
            }
        }
    }
}

